function attr(o={}){ return Object.entries(o).filter(([,v])=>v!==false&&v!==undefined&&v!==null).map(([k,v])=>v===true?k:`${k}="${esc(v)}"`).join(' '); }
function badges(items=[]){ return items.length ? `<div class="status-row">${items.map(x=>`<span class="status-badge">${esc(x)}</span>`).join('')}</div>` : ''; }
function actions(items=[]){ return items.length ? `<div class="vh-actions">${items.map(a=> a.button ? `<button class="vh-button ${a.kind||''}" type="button" ${attr(a.attrs)}>${esc(a.label)}</button>` : `<a class="vh-button ${a.kind||''}" href="${esc(a.href)}" ${a.external?'target="_blank" rel="noopener noreferrer"':''}>${esc(a.label)}</a>`).join('')}</div>` : ''; }
function p(items){ return `<div class="vh-section-copy">${items.map(x=>`<p>${x}</p>`).join('')}</div>`; }
function cards(items, cols='two', portal=false){ return `<div class="vh-grid ${cols}">${items.map(c=>`<article class="${portal?'world-portal-card':c.trace?'trace-card':'vh-card'} reveal" ${c.futureHero?`data-future-hero="${esc(c.futureHero)}"`:''}>${badges(c.badges)}<h3>${esc(c.title)}</h3>${c.text?`<p>${c.text}</p>`:''}${c.html||''}${actions(c.actions||[])}</article>`).join('')}</div>`; }
function kv(items){ return `<dl class="vh-kv">${items.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${b}</dd></div>`).join('')}</dl>`; }
function section(title, body, o={}){ return `<section class="vh-section ${o.className||''}" ${o.id?`id="${esc(o.id)}"`:''}><div class="vh-wrap"><div class="vh-section-head reveal">${o.kicker?`<p class="vh-eyebrow">${esc(o.kicker)}</p>`:''}<h2 class="vh-section-title">${esc(title)}</h2></div><div class="reveal">${body}</div></div></section>`; }
function hero(page){ const hp=page.hero||{}; return `<section class="vh-hero ${hp.compact?'vh-hero-compact':''}" aria-labelledby="page-title"><div class="vh-hero-media" data-future-hero="${esc(hp.image||h('veritas-humanum-hero'))}"></div><div class="vh-wrap vh-hero-grid"><div class="vh-hero-copy reveal">${hp.kicker?`<p class="vh-kicker">${esc(hp.kicker)}</p>`:''}<h1 class="vh-title ${hp.medium?'vh-title-medium':''}" id="page-title">${esc(hp.title||page.title)}</h1>${hp.subtitle?`<p class="vh-subtitle">${esc(hp.subtitle)}</p>`:''}${hp.lead?`<p class="vh-lead">${esc(hp.lead)}</p>`:''}${badges(hp.badges)}${actions(hp.actions)}</div>${hp.panel?`<aside class="vh-hero-panel reveal">${hp.panel}</aside>`:''}</div></section>`; }
function crumb(page){ if(page.route==='/'||page.route==='/pl/') return ''; return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="${page.lang==='pl'?'/pl/':'/'}">Veritas Humanum</a> <span aria-hidden="true">/</span> <span>${esc(page.crumb||page.hero?.title||page.title)}</span></nav>`; }
function footer(lang){ const pl=lang==='pl'; const links=pl?[['Rap-Ort','/rap-ort/pl/'],['SZTAB','/sztab/pl/'],['Muzyka','/music/pl/'],['Dla instytucji','/for-institutions/pl/'],['Kontakt','/contact/pl/']]:[['Rap-Ort','/rap-ort/'],['SZTAB','/sztab/'],['Music','/music/'],['For Institutions','/for-institutions/'],['Contact','/contact/']]; return `<footer class="vh-footer"><div class="vh-wrap vh-footer-grid"><div><p class="vh-eyebrow">VERITAS HUMANUM</p><p>${pl?'Autorskie uniwersum pamięci, muzyki, obrazu i sumienia.':'An authorial universe of memory, music, image and conscience.'}</p><p><a href="mailto:${EMAIL}">${EMAIL}</a></p></div><nav class="vh-footer-links">${links.map(([l,u])=>`<a href="${u}">${l}</a>`).join('')}</nav></div></footer>`; }
function modal(lang){ return `<div class="manifesto-modal" id="manifestoModal" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="manifestoTitle" data-youtube-id=""><div class="manifesto-dialog"><div class="manifesto-dialog-head"><h2 id="manifestoTitle">${lang==='pl'?'Film-manifest Veritas Humanum':'Veritas Humanum Manifesto Film'}</h2><button class="manifesto-close" type="button" data-close-manifesto aria-label="${lang==='pl'?'Zamknij':'Close'}">×</button></div><div class="manifesto-frame" data-manifesto-frame><div class="manifesto-placeholder">${lang==='pl'?'Modal filmu-manifestu jest przygotowany. Dodaj ID filmu YouTube, kiedy materiał będzie gotowy.':'The manifesto film modal is ready. Add a YouTube video ID when the film is available.'}</div></div></div></div>`; }
function ld(page){ return page.jsonLd?.length ? page.jsonLd.map(x=>`<script type="application/ld+json">${JSON.stringify(x)}</script>`).join('\n') : ''; }
function html(page){ const canonical=SITE+page.route; const alt=pairs.get(page.route); return `<!doctype html><html lang="${page.lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(page.title)}</title><meta name="description" content="${esc(page.description)}"><link rel="canonical" href="${canonical}">${alt?`<link rel="alternate" hreflang="${page.lang==='pl'?'en':'pl'}" href="${SITE+alt}">`:''}<link rel="alternate" hreflang="x-default" href="${SITE}/"><meta property="og:type" content="website"><meta property="og:title" content="${esc(page.ogTitle||page.title)}"><meta property="og:description" content="${esc(page.ogDescription||page.description)}"><meta property="og:url" content="${canonical}"><meta property="og:site_name" content="Veritas Humanum"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/assets/css/main.css"><link rel="stylesheet" href="/assets/css/navbar.css"><link rel="stylesheet" href="/assets/css/mobile-nav.css"><link rel="stylesheet" href="/assets/css/cinematic.css"><link rel="stylesheet" href="/assets/css/hub.css"><link rel="stylesheet" href="/assets/css/veritas.css">${ld(page)}</head><body class="veritas-universe vh-page ${esc(page.bodyClass||'')}" data-lang="${page.lang}" data-veritas="true" data-page="${esc(page.id||'')}"><a class="skip-link" href="#main">${page.lang==='pl'?'Przejdź do treści':'Skip to content'}</a><header class="site-header" role="banner"></header>${crumb(page)}<main class="vh-main" id="main">${hero(page)}${page.content}</main>${footer(page.lang)}${page.modal?modal(page.lang):''}<button class="reduced-motion-toggle" type="button" data-reduce-motion-toggle aria-pressed="false">Reduce Motion</button><button class="scroll-top" id="scrollTopButton" type="button" aria-label="${page.lang==='pl'?'Wróć na górę':'Back to top'}">↑</button><script src="/assets/js/main.js" defer></script><script src="/assets/js/navigation.js" defer></script><script src="/assets/js/transitions.js" defer></script><script src="/assets/js/cinematic.js" defer></script><script src="/assets/js/veritas.js" defer></script></body></html>`; }
function write(page){ const f=fileFor(page.route); ensure(f); fs.writeFileSync(f, html(page)); }
function redirect(route,target,lang='en'){ const f=fileFor(route); ensure(f); fs.writeFileSync(f, `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Redirecting</title><link rel="canonical" href="${SITE+target}"><meta http-equiv="refresh" content="0; url=${target}"></head><body><p><a href="${target}">Continue</a></p></body></html>`); }
