 ['/music-works/','/music/','en'],['/music-works/pl/','/music/pl/','pl'],['/pl/music/','/music/pl/','pl'],['/pl/institutions/','/for-institutions/pl/','pl'],['/pl/press/','/press-recognition/pl/','pl'],['/institutions/','/for-institutions/','en'],['/press/','/press-recognition/','en'],['/author/','/authorial-profile/','en'],['/sztab/original/','/sztab/origins/','en'],['/sztab/original/pl/','/sztab/origins/pl/','pl'],['/sztab/original/zo/','/sztab/origins/','en'],['/sztab/original/zo/pl/','/sztab/origins/pl/','pl'],['/rap-ort/prawda-sumienia/viewer/','/rap-ort/witness-report/','en'],['/rap-ort/prawda-sumienia/widz/','/rap-ort/raport-swiadka/','pl'],['/rap-ort/conscience-report/pl/','/rap-ort/pl/','pl']
